package wallet

import (
	"errors"
	"strings"
	"testing"
	"time"
)

func TestTmpRestoreNegativeWaitApprovalDisabled(t *testing.T) {
	start := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	w := New()
	if _, err := w.CreateAccount("payer", 100); err != nil {
		t.Fatal(err)
	}
	if _, err := w.CreateAccount("user", 0); err != nil {
		t.Fatal(err)
	}
	if _, err := w.CreateSession("s1", "user", "dev1", start.Add(24*time.Hour)); err != nil {
		t.Fatal(err)
	}
	spec := PolicySpec{
		ID:                "pol",
		PayerAccountID:    "payer",
		AllowedAccountIDs: []string{"user"},
		Operation:         "op",
		Payee:             "payee",
		StartsAt:          start,
		EndsAt:            start.Add(24 * time.Hour),
		MaxPerRequest:     50,
		MaxTotal:          100,
		ApprovalThreshold: 0,
		ApprovalWait:      -time.Second,
	}
	if err := w.SavePolicy(spec); err != nil {
		t.Fatalf("save policy with negative wait and disabled approval: %v", err)
	}
	if _, err := w.Apply(RequestInput{
		PolicyID: "pol", RequestID: "r1", AccountID: "user", SessionID: "s1",
		DeviceID: "dev1", Operation: "op", Payee: "payee", EstimatedFee: 20,
	}); err != nil {
		t.Fatal(err)
	}
	data, err := w.Export()
	if err != nil {
		t.Fatal(err)
	}
	w2, err := Restore(data)
	if err != nil {
		t.Fatalf("restore must accept negative wait when approval disabled: %v", err)
	}
	pv, err := w2.Policy("pol")
	if err != nil {
		t.Fatal(err)
	}
	if pv.Spec.ApprovalWait != -time.Second {
		t.Fatalf("approval wait not preserved: got %v", pv.Spec.ApprovalWait)
	}
	if pv.Spec.ApprovalThreshold != 0 {
		t.Fatalf("threshold changed: %d", pv.Spec.ApprovalThreshold)
	}
	bal, err := w2.Balance("payer")
	if err != nil {
		t.Fatal(err)
	}
	if bal.Available != 80 || bal.Reserved != 20 {
		t.Fatalf("balances: got %+v", bal)
	}
	rv, err := w2.Request("user", "r1")
	if err != nil {
		t.Fatal(err)
	}
	if rv.State != RequestReserved {
		t.Fatalf("request state: %v", rv.State)
	}
	// 结算实际费用 5：可用 95，预留 0。
	if _, err := w2.Settle("user", "r1", 5); err != nil {
		t.Fatal(err)
	}
	bal, _ = w2.Balance("payer")
	if bal.Available != 95 || bal.Reserved != 0 {
		t.Fatalf("after settle: got %+v", bal)
	}
	// 再导出仍保留负等待时长。
	data2, err := w2.Export()
	if err != nil {
		t.Fatal(err)
	}
	w3, err := Restore(data2)
	if err != nil {
		t.Fatalf("re-restore: %v", err)
	}
	pv3, _ := w3.Policy("pol")
	if pv3.Spec.ApprovalWait != -time.Second {
		t.Fatalf("re-export lost wait: %v", pv3.Spec.ApprovalWait)
	}
	// 新申请仍直接预留。
	if _, err := w3.CreateSession("s2", "user", "dev1", start.Add(48*time.Hour)); err != nil {
		t.Fatal(err)
	}
	rv2, err := w3.Apply(RequestInput{
		PolicyID: "pol", RequestID: "r2", AccountID: "user", SessionID: "s2",
		DeviceID: "dev1", Operation: "op", Payee: "payee", EstimatedFee: 10,
	})
	if err != nil {
		t.Fatal(err)
	}
	if rv2.State != RequestReserved {
		t.Fatalf("new request should reserve directly, got %v", rv2.State)
	}
}

func TestTmpRestorePositiveThresholdStillStrict(t *testing.T) {
	mk := func(waitNanos int64) []byte {
		return []byte(`{"version":1,"exported_at":"2026-01-01T00:00:00Z",
			"accounts":[{"id":"payer","available":100,"reserved":0,"created_at":"2026-01-01T00:00:00Z"}],
			"sessions":[],
			"policies":[{"id":"pol","payer_account_id":"payer","allowed_account_ids":["payer"],
				"operation":"op","payee":"payee","starts_at":"2026-01-01T00:00:00Z","ends_at":"2026-01-02T00:00:00Z",
				"max_per_request":50,"max_total":100,"approval_threshold":10,"approval_wait_nanos":` +
			itoa(waitNanos) + `,"max_reserve_duration_nanos":0,"reserved_total":0,"spent_total":0,
				"deactivated":false,"deactivated_at":"","deactivator_account_id":"","deactivate_reason":""}],
			"requests":[],"ledger":[]}`)
	}
	for _, wait := range []int64{0, -1} {
		_, err := Restore(mk(wait))
		if !errors.Is(err, ErrBackupInvalid) {
			t.Fatalf("wait=%d: want ErrBackupInvalid, got %v", wait, err)
		}
		if !strings.Contains(err.Error(), `"pol"`) || !strings.Contains(err.Error(), "approval wait") {
			t.Fatalf("wait=%d: error should name policy and wait setting: %v", wait, err)
		}
	}
	// 关闭审批但最长预留时长为负：仍须拒绝。
	bad := []byte(`{"version":1,"exported_at":"2026-01-01T00:00:00Z",
		"accounts":[{"id":"payer","available":100,"reserved":0,"created_at":"2026-01-01T00:00:00Z"}],
		"sessions":[],
		"policies":[{"id":"pol","payer_account_id":"payer","allowed_account_ids":["payer"],
			"operation":"op","payee":"payee","starts_at":"2026-01-01T00:00:00Z","ends_at":"2026-01-02T00:00:00Z",
			"max_per_request":50,"max_total":100,"approval_threshold":0,"approval_wait_nanos":-1,
			"max_reserve_duration_nanos":-5,"reserved_total":0,"spent_total":0,
			"deactivated":false,"deactivated_at":"","deactivator_account_id":"","deactivate_reason":""}],
		"requests":[],"ledger":[]}`)
	if _, err := Restore(bad); !errors.Is(err, ErrBackupInvalid) {
		t.Fatalf("negative max reserve duration must be rejected, got %v", err)
	}
}

func itoa(n int64) string {
	if n < 0 {
		return "-" + itoa(-n)
	}
	if n == 0 {
		return "0"
	}
	digits := ""
	for n > 0 {
		digits = string(rune('0'+n%10)) + digits
		n /= 10
	}
	return digits
}

